const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const button=a=>`[data-deck="0"][data-action="${a}"]`,click=s=>{assert($(s),'Missing '+s);$(s).click();};
const files=['app.js','engine.js','stems.js','panels.js','keylock.js','keylock-worker.js','keylock-dsp.js','smart-sync.js','beatgrid.js','warp-loop.js','warp-loop-kernel.js','warp-loop-worklet.js','reverse-censor-plan.js','stem-reverse-162-harness.js','stem-activation-capture-145.js','stem-history-worklet.js','keylock-shadow-live.js','vendor/signalsmith-stretch/SignalsmithStretch-open-play-replace.mjs','vendor/signalsmith-stretch/SignalsmithStretch-open-play-reference-dsp.mjs'];
const sha=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>{const response=await fetch(f,{cache:'no-store'});assert(response.ok,f);return[f,await sha(await response.arrayBuffer())];})));}
async function until(fn,label,ms=30000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function input(selector,value){const element=$(selector);assert(element,'Missing '+selector);element.value=String(value);element.dispatchEvent(new Event('input',{bubbles:true}));}
function base64(bytes){let value='';for(let i=0;i<bytes.length;i+=16384)value+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(value);}
let app,readiness;
async function run(){
 clearInterval(readiness);$('#music-run').disabled=true;
 const {engine,state}=app,deck=state.decks[0],witnesses=[];
 const r={checkpoint:150,diagnosticCheckpoint:162,samples:[],startedAt:new Date().toISOString(),criteria:{minimumRMS:1e-5,maximumStoppedPeak:1e-7,maximumPositionError:.01},scope:'Actual cached real musical Stems; reverse seek/tempo/key/Stop ownership, physically muted internal PCM. Not pitch quality/reference/native/hardware acceptance.',stages:[],progress:[],errors:[]};let observer,original,track;
 function snapshot(){const v=engine.voices.get(0);return{at:engine.ctx.currentTime,position:engine.position(deck),playing:deck.playing,processing:deck.processing,reverse:deck.reverse,rate:deck.rate,keylock:deck.keylock,keyShift:deck.keyShift,syncState:deck.syncState,voice:!!v,gridReverse:v?.gridTimeline?.reverse||false,anchorTime:deck.anchorTime,anchorPosition:deck.anchorPosition,live:!!v?.liveKeylock,mask:[...deck.stems],gains:v?.stemGains?.map(g=>g.gain.value),pending:engine.transforms.has(0),retiring:engine.retiringVoices.get(0)?.size||0};}
 async function pause(){if(deck.playing||deck.processing)click(button('play'));await until(()=>!deck.playing&&!deck.processing,'Pause');}
 function mask(values){for(let p=0;p<4;p++)if(deck.stems[p]!==values[p])click(button('pad')+`[data-pad="${p}"]`);assert(JSON.stringify(deck.stems)===JSON.stringify(values),'Actual pad mask');}
 async function capture(seconds=.4){return Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),10000);w.port.onmessage=async({data})=>{if(data.type==='done'){clearTimeout(timer);resolve({channel:w.channel,startFrame:data.startFrame,frames:data.data.length,quanta:data.quanta,errors:data.errors,sha256:await sha(data.data.buffer),base64:base64(new Uint8Array(data.data.buffer))});}};w.port.postMessage({type:'capture',id:'controls162',frames:Math.round(seconds*engine.ctx.sampleRate)});})));}
 async function probe(name){const row={name,before:snapshot()};r.stages.push(row);assert(row.before.playing&&row.before.reverse&&row.before.rate>0,'Reverse playback state '+name);row.pcm=await capture();row.after=snapshot();assert(row.after.position<row.before.position&&row.after.reverse,'Original-coordinate reverse '+name);assert(row.after.playing,'Early end '+name);}
 const reverse=()=>{document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'Q',code:'KeyQ',shiftKey:true,bubbles:true,cancelable:true}));document.body.dispatchEvent(new KeyboardEvent('keyup',{key:'q',code:'KeyQ',bubbles:true,cancelable:true}));};
 try{
  r.sourceBefore=await identities();await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute required');
  track=state.tracks.find(t=>t.file?.name==='SDRNR-private-research-159.mp3');assert(track?.contentHash==='cb2e756d1fa4ce264767a4f6adbaf9e3f69a040db7889d830abdb429cc1a5ac3','Actual expected imported file');await until(()=>!state.analysis&&$('#analyze').textContent==='Analyze','Imported analysis');
  r.import={id:track.id,contentHash:track.contentHash,filename:track.file.name,bytes:track.file.size,type:track.type,storage:track.storage,duration:track.duration};click(`[data-track="${track.id}"]`);click(button('load'));await until(()=>deck.track===track&&!deck.processing,'Actual deck Load');
  original=await engine.buffer(track);r.input={frames:original.length,sampleRate:original.sampleRate,channels:original.numberOfChannels,duration:original.duration};assert(track.duration===original.duration&&original.duration>3.5,'Imported duration');r.originalHashes=await Promise.all([0,1].map(c=>sha(original.getChannelData(c).buffer)));
  assert(deck.rate===1&&!deck.keylock&&!deck.keyShift&&!deck.loop&&!deck.reverse&&!deck.sync,'Neutral loaded transport');assert(state.fx.every(unit=>unit.every(slot=>!slot.on))&&deck.stemFX.every(v=>!v),'No FX');
  for(const k of ['low','mid','high','filter'])input(`[data-mix="0:${k}"]`,0);input('[data-track-gain="0"]',0);await sleep(250);
  click(button('tab')+'[data-tab="Stems"]');click(button('stemPrepare'));const output=$('#stems-state');observer=new MutationObserver(()=>{r.progress.push({at:performance.now(),text:output.textContent});$('#music-status').textContent=output.textContent;});observer.observe(output,{childList:true,subtree:true,characterData:true});click('#stems-queue');await until(()=>!$('#stems-queue').disabled&&/^(Ready|Failed)/.test(track.stemState),'Actual musical preparation',120000);assert(track.stemState.startsWith('Ready'),track.stemState);
  r.ready={status:output.textContent,job:track.stemJob,model:track.stemModel,buffers:engine.stemBuffers.get(track.id).map(b=>({frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels,duration:b.duration}))};const response=await fetch('/api/stems/'+track.stemJob);assert(response.ok,'Real job');r.job=await response.json();assert(r.job.state==='complete'&&r.job.model==='SCNet-large official','Actual real separation');assert(r.ready.buffers.length===4&&r.ready.buffers.every(b=>b.frames===original.length&&b.channels===2&&b.sampleRate===original.sampleRate),'Actual output lengths');click('#modal-close');
  await engine.ctx.audioWorklet.addModule(new URL('./stem-activation-capture-145.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.nodes[0].monitorTap.connect(split);for(let c=0;c<2;c++){const w=new AudioWorkletNode(engine.ctx,'open-play-stem-activation-145-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});w.channel=c;split.connect(w,c);w.connect(engine.ctx.destination);witnesses.push(w);}r.sampleRate=engine.ctx.sampleRate;
  click(button('grid'));$('#grid-bpm').value='120';$('#grid-offset').value='0';click('#grid-clear');for(const marker of [{time:1,bpm:150},{time:1.8,bpm:90}]){$('#grid-warp-time').value=marker.time;$('#grid-warp-bpm').value=marker.bpm;click('#grid-marker');}click('#grid-save');await until(()=>!$('#modal').open,'Save grid');
  click('[data-panel="settings"]');const setting=$('[data-setting="Sync Mode"]');setting.value='Smart Sync';setting.dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');
  async function seek(position){const el=$('[data-seek="0"]');if(position===track.duration){el.dispatchEvent(new KeyboardEvent('keydown',{key:'End',bubbles:true}));await until(()=>engine.position(deck)===track.duration&&!deck.processing,'Seek End');return;}el.dispatchEvent(new KeyboardEvent('keydown',{key:'Home',bubbles:true}));await until(()=>engine.position(deck)===0&&!deck.processing,'Seek Home');for(let n=0;n<position;n++){el.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));await until(()=>Math.abs(engine.position(deck)-(n+1))<1e-8&&!deck.processing,'Seek '+(n+1));}}
  click(button('tab')+'[data-tab="Stems"]');mask([false,true,true,true]);r.grid={bpm:track.bpm,offset:track.grid,markers:track.gridWarpMarkers};
  await seek(5);click(button('sync'));await until(()=>deck.sync,'Sync');reverse();await until(()=>deck.reverse&&!deck.processing,'Reverse armed');click(button('play'));await until(()=>deck.playing&&!deck.processing,'Reverse Play');
  // Actual seek across the1.8-second marker while playback is running.
  const seekEl=$('[data-seek="0"]'),box=seekEl.getBoundingClientRect();seekEl.dispatchEvent(new MouseEvent('click',{clientX:box.left+1.6/track.duration*seekEl.clientWidth,clientY:box.top+20,bubbles:true}));await until(()=>!deck.processing&&deck.playing&&engine.position(deck)<1.7,'Reverse seek marker');await probe('reverse-seek-across-marker');
  await pause();await seek(5);click(button('play'));await until(()=>deck.playing&&!deck.processing,'Rate start');input('[data-tempo="0"]',6);await until(()=>!deck.processing&&Math.abs(deck.rate-1.06)<.001,'Tempo+6%');await probe('reverse-tempo-change');
  click(button('keyUp'));await until(()=>!deck.processing&&deck.keyShift===1&&deck.playing,'Live key+1');await until(()=>engine.ctx.currentTime>deck.anchorTime+.08,'Key anchor');await probe('reverse-key-change');
  // Start actual replacement preparation, then actual Pause in the same event turn.
  const cancel={name:'stop-during-reverse-key-preparation',before:snapshot()};r.stages.push(cancel);click(button('keyUp'));cancel.pending=snapshot();assert(cancel.pending.processing&&cancel.pending.pending,'No real pending preparation');click(button('play'));cancel.stopped=snapshot();await sleep(1200);cancel.settled=snapshot();cancel.pcm=await capture();cancel.after=snapshot();assert(!cancel.after.playing&&!cancel.after.processing&&!cancel.after.voice&&!cancel.after.pending&&!cancel.after.retiring,'Stop resurrected owner');
  // Endpoint semantics: Home while playing stops at original0, End can start reverse.
  await seek(track.duration);click(button('play'));await until(()=>deck.playing&&!deck.processing,'Reverse from End');await probe('reverse-from-track-end');$('[data-seek="0"]').dispatchEvent(new KeyboardEvent('keydown',{key:'Home',bubbles:true}));await until(()=>!deck.playing&&!deck.processing,'Home stops reverse');r.home=snapshot();assert(r.home.position===0&&!r.home.voice,'Home endpoint');
  r.originalUnchanged=JSON.stringify(r.originalHashes)===JSON.stringify(await Promise.all([0,1].map(c=>sha(original.getChannelData(c).buffer))));r.importedFileUnchanged=await sha(await track.file.arrayBuffer())===r.import.contentHash;assert(r.originalUnchanged&&r.importedFileUnchanged,'Input changed');r.workflowExecuted=true;
 }catch(error){r.errors.push({message:error.message,stack:error.stack});r.failureState={...snapshot(),notifications:document.body.innerText.slice(-1600)};}
 finally{
  observer?.disconnect();for(const d of state.decks)engine.pause(d);for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.workflowCompleted=!!r.workflowExecuted&&!r.errors.length&&r.sourceStable;r.finishedAt=new Date().toISOString();const raw=JSON.stringify(r),id=crypto.randomUUID().replaceAll('-','');let receipt;
  try{const response=await fetch('/api/test-evidence/stem-resource-150/'+id,{method:'POST',headers:{'Content-Type':'application/json','X-Open-Play':'local-prototype'},body:raw});assert(response.ok,'Save failed');receipt=await response.json();const bytes=new TextEncoder().encode(raw);assert(receipt.bytes===bytes.length&&receipt.sha256===await sha(bytes),'Receipt mismatch');}catch(error){receipt={id,error:error.message};}
  const summary={workflowCompleted:r.workflowCompleted,sourceStable:r.sourceStable,stages:r.stages.map(({pcm,...s})=>s),errors:r.errors,failureState:r.failureState,receipt};$('#music-original').textContent=JSON.stringify(summary);$('#music-results').textContent=JSON.stringify(summary,null,2);$('#music-status').textContent=r.workflowCompleted?'Controls recorded; independent inspection pending':'Failed workflow retained';
 }
}
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'App');app=window.openPlay;app.engine.init();app.engine.audioMonitor.mutePhysical(true);$('#music-status').textContent='Import the private research MP3 using Import audio below';readiness=setInterval(()=>{if(app.state.tracks.some(t=>t.file?.name==='SDRNR-private-research-159.mp3')){$('#music-run').disabled=false;$('#music-status').textContent='Imported file available; ready';}},250);}
$('#music-run').onclick=()=>run();boot().catch(error=>$('#music-status').textContent=error.message);
